// ==================== HELPER FUNCTIONS ====================

/**
 * Get all units for a given book.
 */
export function getUnitsByBook(bookId) {
  return bookUnits[bookId] || [];
}

/**
 * Get all words for a specific book and unit.
 */
export function getWordsByBookUnit(bookId, unitId) {
  return allWords.filter(w => {
    const book = books.find(b => b.id === bookId);
    return book && w.grade === book.grade && w.unit === unitId;
  });
}

/**
 * Get all words for a specific book.
 */
export function getWordsByBook(bookId) {
  const book = books.find(b => b.id === bookId);
  if (!book) return [];
  return allWords.filter(w => w.grade === book.grade);
}

/**
 * Get all words.
 */
export function getAllWords() {
  return allWords;
}

/**
 * Get a single word by ID.
 */
export function getWordById(id) {
  return allWords.find(w => w.id === id);
}

/**
 * Get words by a list of IDs (for wrong word review).
 */
export function getWordsByIds(ids) {
  return ids.map(id => allWords.find(w => w.id === id)).filter(Boolean);
}

